import sys

def main():
    s = sys.stdin.read().split()[0]
    open_cnt = 0
    pairs = 0
    for ch in s:
        if ch == '(':
            open_cnt += 1
        elif open_cnt > 0:
            open_cnt -= 1
            pairs += 1
    print(2 * pairs)

