s = sys.stdin.read().split()[0]
n = len(s)
dp = [[0] * (n + 2) for _ in range(n + 2)]
for length in range(1, n + 1):
    for i in range(0, n - length + 1):
        j = i + length - 1
        best = dp[i + 1][j]
        if s[i] == '(':
            for k in range(i + 1, j + 1):
                if s[k] == ')':
                    best = max(best, 2 + dp[i + 1][k - 1] + dp[k + 1][j])
        dp[i][j] = best
print(dp[0][n - 1])

